import pytest
from concurrent.futures import ThreadPoolExecutor


def parity(x: int) -> int:
    """Return 0 if x is even and 1 if x is odd."""
    return x % 2


def parities(xs: list[int]) -> list[int]:
    """Return the parity of each element of xs, in input order.

    Each element is computed with parity() on a thread pool. The result
    order matches the input order and does not depend on the number of
    workers used.
    """
    if not xs:
        return []
    with ThreadPoolExecutor() as pool:
        return list(pool.map(parity, xs))


def test_parity() -> None:
    assert parity(0) == 0
    assert parity(7) == 1
    assert parity(-3) == 1


def test_parities_small() -> None:
    assert parities([5, 2, 7, 8]) == [1, 0, 1, 0]


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_negative() -> None:
    assert parities([-1, -2, 0]) == [1, 0, 0]


def test_parities_preserves_order_on_large_input() -> None:
    xs = list(range(10_000))
    assert parities(xs) == [x % 2 for x in xs]


def test_parities_does_not_mutate_input() -> None:
    xs = [3, 4, 5]
    parities(xs)
    assert xs == [3, 4, 5]


@pytest.mark.parametrize("n", [1, 2, 3, 17])
def test_parities_length_matches_input(n: int) -> None:
    xs = list(range(n))
    assert len(parities(xs)) == n
